import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

import { decodeMapperSubmode, parsePonchoRom } from '../../src/core/cart-poncho/header';
import { detectConsole } from '../../src/console/detect';
import { PonchoNes } from '../../src/console/poncho-nes';
import { testRomPath } from '../rom-paths';

/**
 * Integration tests for synthetic PonchoROMs under tests/roms/poncho/.
 * These ROMs are generated by scripts in scripts/gen-poncho-rom/ and
 * committed to the repo. The test re-parses them from disk to prove
 * the writer + parser agree at the byte level, not just in memory.
 */

describe('synthetic PonchoROM: solid-bg', () => {
  const path = testRomPath('poncho/solid-bg.poncho');

  it.skipIf(!existsSync(path))('parses with the expected header and palette', () => {
    const data = new Uint8Array(readFileSync(path));
    const { header, paletteOffset, paletteByteLength } = parsePonchoRom(data);

    expect(header.title).toBe('Solid BG (synthetic)');
    expect(header.paletteCount).toBe(1);
    expect(header.prgSizeKb).toBe(1);
    expect(header.chrSizeKb).toBe(1);
    expect(header.flags.upscaledMode).toBe(false);
    expect(header.tvSystem).toBe('ntsc');
    expect(header.mapperId).toBe(1);

    // Palette entry 0 = the universal background colour the script declared.
    const palette = data.subarray(paletteOffset, paletteOffset + paletteByteLength);
    expect(palette).toEqual(new Uint8Array([0xe6, 0x3e, 0x32, 0xff]));
  });

  it.skipIf(!existsSync(path))('exists on disk at the expected size', () => {
    const data = readFileSync(path);
    // Header (64) + palette (1×4) + PRG (1024) + CHR (1024) = 2116
    expect(data.length).toBe(2116);
  });

  it.skipIf(!existsSync(path))(
    'detect → load → runFrame produces a 1024×960 frame of the BG colour',
    () => {
      const data = new Uint8Array(readFileSync(path));

      const factory = detectConsole(data);
      expect(factory).not.toBeNull();
      expect(factory!.spec.id).toBe('poncho-nes');

      const console = factory!.create();
      expect(console).toBeInstanceOf(PonchoNes);

      console.loadRom(data);
      const fb = console.runFrame();

      expect(fb.width).toBe(1024);
      expect(fb.height).toBe(960);

      // R=0xE6, G=0x3E, B=0x32, A=0xFF → ABGR-packed = 0xFF323EE6.
      const expected = 0xff323ee6;
      expect(fb.data[0]).toBe(expected);
      expect(fb.data[fb.width * fb.height - 1]).toBe(expected);
      expect(fb.data[fb.width * Math.floor(fb.height / 2) + fb.width / 2]).toBe(expected);
      // Cheap full-buffer uniformity check: any non-matching pixel?
      let mismatches = 0;
      for (let i = 0; i < fb.data.length; i++) {
        if (fb.data[i] !== expected) { mismatches++; if (mismatches > 4) break; }
      }
      expect(mismatches).toBe(0);
    },
  );
});

describe('synthetic PonchoROM: palette-write', () => {
  const path = testRomPath('poncho/palette-write.poncho');

  it.skipIf(!existsSync(path))(
    'PRG writes master-index 5 to $3F00; framebuffer becomes magenta',
    () => {
      const data = new Uint8Array(readFileSync(path));
      const factory = detectConsole(data);
      expect(factory).not.toBeNull();
      expect(factory!.spec.id).toBe('poncho-nes');

      const console = factory!.create();
      console.loadRom(data);
      const fb = console.runFrame();

      // Master palette index 5 in palette-write.ts = magenta (255, 0, 255).
      // ABGR pack of (0xFF, 0x00, 0xFF) = 0xFFFF00FF.
      const expected = 0xffff00ff;
      expect(fb.data[0]).toBe(expected);
      expect(fb.data[fb.data.length - 1]).toBe(expected);
      let mismatches = 0;
      for (let i = 0; i < fb.data.length; i++) {
        if (fb.data[i] !== expected) { mismatches++; if (mismatches > 4) break; }
      }
      expect(mismatches).toBe(0);
    },
  );
});

